(() => {
  document.body.classList.add('pdp-page');
  document.querySelector('.crumbs').hidden=true;
  const pictures=[['assets/pdp-pack.png','Karseell Collagen Hair Mask'],['assets/hair-after.png','Smooth hair results'],['assets/pdp-shine.png','Noticeable shine and softness'],['assets/pdp-ingredients.png','Argan oil and collagen'],['assets/pdp-brand.png','Karseell intensive care'],['assets/pdp-scenario.png','Complete hair repair'],['assets/pdp-ritual.png','How to use']];
  document.querySelector('.product-hero').innerHTML=`<div class="gallery"><div class="gallery-main"><button class="gallery-arrow gallery-prev" type="button" aria-label="Previous product image">‹</button><img id="mainProductImage" src="assets/pdp-pack.png" alt="Karseell Collagen Hair Mask" /><button class="gallery-arrow gallery-next" type="button" aria-label="Next product image">›</button></div><div class="thumbs">${pictures.map(([src,alt],index)=>`<button class="thumb ${index===0?'is-active':''}" type="button" data-gallery-index="${index}" aria-label="Show ${alt}" aria-pressed="${index===0}"><img src="${src}" alt="${alt}" /></button>`).join('')}</div></div><div class="product-info"><div class="product-badges"><span>BESTSELLERS</span><span>20% off</span></div><p class="eyebrow">DEEP REPAIR TREATMENT</p><h1>Karseell Collagen Hair<br class="pdp-title-break" /> Mask</h1><a class="stars pdp-rating" href="#reviews">★★★★★ <span>4.8/5 from 393 customer reviews</span></a><p class="description">Infused with argan oil and hydrolyzed proteins, this deeply nourishing mask repairs dry, damaged and color-treated hair from the first use. Just 5–10 minutes to softer, shinier, healthier-looking hair.</p><ul class="features"><li><strong>Deep repair:</strong> deeply hydrates and restores dry, damaged hair</li><li><strong>Frizz control:</strong> smooths rough texture for all-day sleekness</li><li><strong>All hair types:</strong> color-treated, bleached, curly, straight, dry or damaged</li></ul><div class="price-line"><strong id="pdpPrice">$15.99</strong><s>$24.99</s><span id="pdpSaving">YOU SAVE $9.00 (36%)</span></div><p class="size-title">Volume</p><div class="sizes"><button class="size is-active" data-size="100" type="button" aria-pressed="true"><strong>100ml</strong><small>Travel size</small></button><button class="size" data-size="500" type="button" aria-pressed="false"><strong>500ml</strong><small>Full size</small></button></div><div class="quantity"><button id="qtyMinus" type="button" aria-label="Decrease quantity">−</button><input id="qty" value="1" inputmode="numeric" aria-label="Quantity" /><button id="qtyPlus" type="button" aria-label="Increase quantity">+</button></div><button class="primary pdp-add" id="pdpAdd" data-add-cart data-product="Karseell Collagen Hair Mask" data-price="15.99" type="button"><span id="pdpAddLabel">$15.99 -- ADD TO BAG</span><small>Spend $100, Get 20% Off<br />Use Code KA20 at</small></button><button class="buy-now" id="pdpBuy" data-add-cart data-product="Karseell Collagen Hair Mask" data-price="15.99" type="button">$24.99 -- BUY NOW</button><article class="pdp-pairing"><img src="assets/essential-3.jpg" alt="Karseell Moroccan Argan Oil" /><div><small>PAIRS WELL WITH</small><h3>Karseell Moroccan Argan Oil for Hair Healing</h3><div class="pairing-stars">★★★★★</div><p>$20.41</p></div><button type="button" data-add-cart data-product="Karseell Moroccan Argan Oil" data-price="20.41" aria-label="Add recommended argan oil">+</button></article></div>`;
  document.querySelector('.product-hero').closest('.page').insertAdjacentHTML('beforebegin',`<div class="pdp-buy-strip"><a href="index.html" class="pdp-mini-product"><img src="assets/editor-1.jpg" alt="Karseell Hair Mask" /><span><strong>Karseell Collagen Hair Mask</strong><br />Collagen mask heals damage &amp; calms frizz for silky hair</span></a><select id="stickySize" aria-label="Product volume"><option value="100">100ml</option><option value="500">500ml</option></select><div class="pdp-strip-quantity"><button id="stickyMinus" type="button" aria-label="Decrease quantity">−</button><span id="stickyQty">1</span><button id="stickyPlus" type="button" aria-label="Increase quantity">+</button></div><button type="button" id="stickyAdd">ADD TO BAG</button></div>`);
  let galleryIndex=0;
  function showImage(index){galleryIndex=(index+pictures.length)%pictures.length;const [src,alt]=pictures[galleryIndex];const image=document.getElementById('mainProductImage');image.src=src;image.alt=alt;document.querySelectorAll('[data-gallery-index]').forEach(button=>{const active=Number(button.dataset.galleryIndex)===galleryIndex;button.classList.toggle('is-active',active);button.setAttribute('aria-pressed',String(active));});}
  document.querySelectorAll('[data-gallery-index]').forEach(button=>button.addEventListener('click',()=>showImage(Number(button.dataset.galleryIndex))));
  document.querySelector('.gallery-prev').addEventListener('click',()=>showImage(galleryIndex-1));document.querySelector('.gallery-next').addEventListener('click',()=>showImage(galleryIndex+1));
  document.getElementById('mainProductImage').addEventListener('keydown',event=>{if(event.key==='ArrowLeft')showImage(galleryIndex-1);if(event.key==='ArrowRight')showImage(galleryIndex+1);});document.getElementById('mainProductImage').tabIndex=0;
  const qty=document.getElementById('qty');const setQty=value=>{qty.value=String(Math.max(1,Math.min(99,Math.floor(Number(value)||1))));document.getElementById('stickyQty').textContent=qty.value;};
  ['qtyMinus','stickyMinus'].forEach(id=>document.getElementById(id).addEventListener('click',()=>setQty(Number(qty.value)-1)));['qtyPlus','stickyPlus'].forEach(id=>document.getElementById(id).addEventListener('click',()=>setQty(Number(qty.value)+1)));qty.addEventListener('change',()=>setQty(qty.value));
  function selectSize(size){document.querySelectorAll('.size').forEach(button=>{const active=button.dataset.size===size;button.classList.toggle('is-active',active);button.setAttribute('aria-pressed',String(active));});document.getElementById('stickySize').value=size;const price=size==='100'?'15.99':'24.99';document.getElementById('pdpPrice').textContent='$'+price;document.getElementById('pdpSaving').textContent=size==='100'?'YOU SAVE $9.00 (36%)':'';document.getElementById('pdpAddLabel').textContent='$'+price+' -- ADD TO BAG';document.getElementById('pdpAdd').dataset.price=price;document.getElementById('pdpBuy').dataset.price=price;}
  document.querySelectorAll('.size').forEach(button=>button.addEventListener('click',()=>selectSize(button.dataset.size)));document.getElementById('stickySize').addEventListener('change',event=>selectSize(event.target.value));document.getElementById('stickyAdd').addEventListener('click',()=>document.getElementById('pdpAdd').click());
  document.querySelector('.formula-visual').removeAttribute('role');document.querySelector('.formula-visual').innerHTML='<img src="assets/pdp-formula-square.png" alt="Karseell hair mask cream texture on a comb" />';
})();
